-- Consolidate overlapping legacy policies into one policy per operation.
-- No UPDATE/DELETE statements touch application data.
do $$ declare p record; begin
  for p in select tablename, policyname from pg_policies where schemaname='public'
    and tablename in ('kullanicilar','kullanici_programlar','programlar','siniflar','dersler','ogrenciler','ogretmen_dersleri','ders_sorumlulari','yoklamalar','notlar','sinavlar','odevler','odev_teslimleri','duyurular','ders_oturumlari','push_abonelikleri')
  loop execute format('drop policy %I on public.%I', p.policyname, p.tablename); end loop;
end $$;
create policy scoped_read on public.kullanicilar for select to authenticated using (id in (select private.visible_user_ids()));
create policy scoped_read on public.kullanici_programlar for select to authenticated using (kullanici_id = (select auth.uid()) or program_id in (select private.program_ids(true)));
create policy scoped_read on public.programlar for select to authenticated using (id in (select private.program_ids(false)));
create policy scoped_read on public.siniflar for select to authenticated using (program_id in (select private.program_ids(false)));
create policy scoped_read on public.dersler for select to authenticated using (sinif_id in (select id from public.siniflar));
create policy scoped_read on public.ogrenciler for select to authenticated using (kullanici_id = (select auth.uid()) or sinif_id in (select private.class_ids()));
create policy scoped_read on public.ogretmen_dersleri for select to authenticated using (ogretmen_id = (select auth.uid()) or ders_id in (select private.lesson_ids(false,false)));
create policy scoped_read on public.ders_sorumlulari for select to authenticated using (ogrenci_id in (select private.student_ids()) or ders_id in (select private.lesson_ids(false,false)));
create policy scoped_read on public.notlar for select to authenticated using (ogrenci_id in (select private.student_ids()) or ders_id in (select private.lesson_ids(true,false)));
create policy scoped_read on public.yoklamalar for select to authenticated using (ogrenci_id in (select private.student_ids()) or ders_id in (select private.lesson_ids(true,true)));
create policy scoped_read on public.sinavlar for select to authenticated using (ders_id in (select id from public.dersler));
create policy scoped_read on public.odevler for select to authenticated using (program_id in (select private.program_ids(false)));
create policy scoped_read on public.odev_teslimleri for select to authenticated using (ogrenci_id in (select private.student_ids()) or ders_id in (select private.lesson_ids(true,false)));
create policy scoped_read on public.ders_oturumlari for select to authenticated using (ders_id in (select id from public.dersler));
create policy scoped_read on public.duyurular for select to authenticated using (program_id in (select private.program_ids(true)) or (program_id in (select private.program_ids(false)) and (hedef_tipi = 'tumu' or hedef_kullanici_id = (select auth.uid()) or hedef_sinif_id in (select sinif_id from public.ogrenciler where kullanici_id=(select auth.uid())))) or (program_id in (select private.program_ids(false)) and hedef_sinif_id in (select private.class_ids())));
create policy scoped_insert on public.siniflar for insert to authenticated with check (program_id in (select private.program_ids(true)));
create policy scoped_update on public.siniflar for update to authenticated using (program_id in (select private.program_ids(true))) with check (program_id in (select private.program_ids(true)));
create policy scoped_delete on public.siniflar for delete to authenticated using (program_id in (select private.program_ids(true)));
create policy scoped_insert on public.dersler for insert to authenticated with check (sinif_id in (select id from public.siniflar where program_id in (select private.program_ids(true))));
create policy scoped_update on public.dersler for update to authenticated using (sinif_id in (select id from public.siniflar where program_id in (select private.program_ids(true)))) with check (sinif_id in (select id from public.siniflar where program_id in (select private.program_ids(true))));
create policy scoped_delete on public.dersler for delete to authenticated using (sinif_id in (select id from public.siniflar where program_id in (select private.program_ids(true))));
create policy scoped_insert on public.ogrenciler for insert to authenticated with check (sinif_id in (select id from public.siniflar where program_id in (select private.program_ids(true))));
create policy scoped_update on public.ogrenciler for update to authenticated using (sinif_id in (select id from public.siniflar where program_id in (select private.program_ids(true)))) with check (sinif_id in (select id from public.siniflar where program_id in (select private.program_ids(true))));
create policy scoped_delete on public.ogrenciler for delete to authenticated using (sinif_id in (select id from public.siniflar where program_id in (select private.program_ids(true))));
create policy scoped_insert on public.ogretmen_dersleri for insert to authenticated with check (ders_id in (select private.lesson_ids(false,false)));
create policy scoped_update on public.ogretmen_dersleri for update to authenticated using (ders_id in (select private.lesson_ids(false,false))) with check (ders_id in (select private.lesson_ids(false,false)));
create policy scoped_delete on public.ogretmen_dersleri for delete to authenticated using (ders_id in (select private.lesson_ids(false,false)));
create policy scoped_insert on public.ders_sorumlulari for insert to authenticated with check (ders_id in (select private.lesson_ids(false,false)) and private.student_matches_lesson(ogrenci_id, ders_id));
create policy scoped_update on public.ders_sorumlulari for update to authenticated using (ders_id in (select private.lesson_ids(false,false)) and private.student_matches_lesson(ogrenci_id, ders_id)) with check (ders_id in (select private.lesson_ids(false,false)) and private.student_matches_lesson(ogrenci_id, ders_id));
create policy scoped_delete on public.ders_sorumlulari for delete to authenticated using (ders_id in (select private.lesson_ids(false,false)) and private.student_matches_lesson(ogrenci_id, ders_id));
create policy scoped_insert on public.notlar for insert to authenticated with check (ders_id in (select private.lesson_ids(true,false)) and private.student_matches_lesson(ogrenci_id, ders_id));
create policy scoped_update on public.notlar for update to authenticated using (ders_id in (select private.lesson_ids(true,false)) and private.student_matches_lesson(ogrenci_id, ders_id)) with check (ders_id in (select private.lesson_ids(true,false)) and private.student_matches_lesson(ogrenci_id, ders_id));
create policy scoped_delete on public.notlar for delete to authenticated using (ders_id in (select private.lesson_ids(true,false)) and private.student_matches_lesson(ogrenci_id, ders_id));
create policy scoped_insert on public.sinavlar for insert to authenticated with check (ders_id in (select private.lesson_ids(true,false)));
create policy scoped_update on public.sinavlar for update to authenticated using (ders_id in (select private.lesson_ids(true,false))) with check (ders_id in (select private.lesson_ids(true,false)));
create policy scoped_delete on public.sinavlar for delete to authenticated using (ders_id in (select private.lesson_ids(true,false)));
create policy scoped_insert on public.yoklamalar for insert to authenticated with check (ders_id in (select private.lesson_ids(true,true)) and private.student_matches_lesson(ogrenci_id, ders_id));
create policy scoped_update on public.yoklamalar for update to authenticated using (ders_id in (select private.lesson_ids(true,true)) and private.student_matches_lesson(ogrenci_id, ders_id)) with check (ders_id in (select private.lesson_ids(true,true)) and private.student_matches_lesson(ogrenci_id, ders_id));
create policy scoped_delete on public.yoklamalar for delete to authenticated using (ders_id in (select private.lesson_ids(true,true)) and private.student_matches_lesson(ogrenci_id, ders_id));
create policy scoped_insert on public.ders_oturumlari for insert to authenticated with check (ders_id in (select private.lesson_ids(true,true)));
create policy scoped_update on public.ders_oturumlari for update to authenticated using (ders_id in (select private.lesson_ids(true,true))) with check (ders_id in (select private.lesson_ids(true,true)));
create policy scoped_delete on public.ders_oturumlari for delete to authenticated using (ders_id in (select private.lesson_ids(true,true)));
create policy scoped_insert on public.odevler for insert to authenticated with check ((program_id in (select private.program_ids(true)) or ders_id in (select private.lesson_ids(true,false))) and (ders_id is null or exists (select 1 from public.dersler d join public.siniflar s on s.id=d.sinif_id where d.id=odevler.ders_id and s.program_id=odevler.program_id)));
create policy scoped_update on public.odevler for update to authenticated using ((program_id in (select private.program_ids(true)) or ders_id in (select private.lesson_ids(true,false))) and (ders_id is null or exists (select 1 from public.dersler d join public.siniflar s on s.id=d.sinif_id where d.id=odevler.ders_id and s.program_id=odevler.program_id))) with check ((program_id in (select private.program_ids(true)) or ders_id in (select private.lesson_ids(true,false))) and (ders_id is null or exists (select 1 from public.dersler d join public.siniflar s on s.id=d.sinif_id where d.id=odevler.ders_id and s.program_id=odevler.program_id)));
create policy scoped_delete on public.odevler for delete to authenticated using ((program_id in (select private.program_ids(true)) or ders_id in (select private.lesson_ids(true,false))) and (ders_id is null or exists (select 1 from public.dersler d join public.siniflar s on s.id=d.sinif_id where d.id=odevler.ders_id and s.program_id=odevler.program_id)));
create policy scoped_insert on public.odev_teslimleri for insert to authenticated with check (ogrenci_id in (select private.student_ids()) and private.student_matches_lesson(ogrenci_id, ders_id) and exists (select 1 from public.odevler o where o.id=odev_id and o.ders_id=odev_teslimleri.ders_id));
create policy scoped_update on public.odev_teslimleri for update to authenticated using (ogrenci_id in (select private.student_ids()) and private.student_matches_lesson(ogrenci_id, ders_id) and exists (select 1 from public.odevler o where o.id=odev_id and o.ders_id=odev_teslimleri.ders_id)) with check (ogrenci_id in (select private.student_ids()) and private.student_matches_lesson(ogrenci_id, ders_id) and exists (select 1 from public.odevler o where o.id=odev_id and o.ders_id=odev_teslimleri.ders_id));
create policy scoped_insert on public.duyurular for insert to authenticated with check (program_id in (select private.program_ids(true)) or (yayinlayan_id=(select auth.uid()) and hedef_tipi='sinif' and exists (select 1 from public.dersler d join public.siniflar s on s.id=d.sinif_id where d.id in (select private.lesson_ids(true,false)) and s.id=hedef_sinif_id and s.program_id=duyurular.program_id)));
create policy scoped_update on public.duyurular for update to authenticated using (program_id in (select private.program_ids(true)) or (yayinlayan_id=(select auth.uid()) and hedef_tipi='sinif' and exists (select 1 from public.dersler d join public.siniflar s on s.id=d.sinif_id where d.id in (select private.lesson_ids(true,false)) and s.id=hedef_sinif_id and s.program_id=duyurular.program_id))) with check (program_id in (select private.program_ids(true)) or (yayinlayan_id=(select auth.uid()) and hedef_tipi='sinif' and exists (select 1 from public.dersler d join public.siniflar s on s.id=d.sinif_id where d.id in (select private.lesson_ids(true,false)) and s.id=hedef_sinif_id and s.program_id=duyurular.program_id)));
create policy scoped_delete on public.duyurular for delete to authenticated using (program_id in (select private.program_ids(true)) or (yayinlayan_id=(select auth.uid()) and hedef_tipi='sinif' and exists (select 1 from public.dersler d join public.siniflar s on s.id=d.sinif_id where d.id in (select private.lesson_ids(true,false)) and s.id=hedef_sinif_id and s.program_id=duyurular.program_id)));
create policy own_profile_update on public.kullanicilar for update to authenticated using (id=(select auth.uid())) with check (id=(select auth.uid()));
create policy super_admin_insert on public.kullanici_programlar for insert to authenticated with check ((select public.get_rol())='super_admin');
create policy super_admin_update on public.kullanici_programlar for update to authenticated using ((select public.get_rol())='super_admin') with check ((select public.get_rol())='super_admin');
create policy super_admin_delete on public.kullanici_programlar for delete to authenticated using ((select public.get_rol())='super_admin');
create policy own_push_insert on public.push_abonelikleri for insert to authenticated with check (kullanici_id=(select auth.uid()));
create policy own_push_delete on public.push_abonelikleri for delete to authenticated using (kullanici_id=(select auth.uid()));
create index if not exists idx_ders_oturumlari_ders_id on public.ders_oturumlari (ders_id);
create index if not exists idx_ders_oturumlari_olusturan_id on public.ders_oturumlari (olusturan_id);
create index if not exists idx_duyurular_hedef_kullanici_id on public.duyurular (hedef_kullanici_id);
create index if not exists idx_duyurular_hedef_sinif_id on public.duyurular (hedef_sinif_id);
create index if not exists idx_duyurular_program_id on public.duyurular (program_id);
create index if not exists idx_duyurular_yayinlayan_id on public.duyurular (yayinlayan_id);
create index if not exists idx_kullanici_programlar_program_id on public.kullanici_programlar (program_id);
create index if not exists idx_notlar_odev_id on public.notlar (odev_id);
create index if not exists idx_notlar_sinav_id on public.notlar (sinav_id);
create index if not exists idx_odev_teslimleri_ders_id on public.odev_teslimleri (ders_id);
create index if not exists idx_odev_teslimleri_ogrenci_id on public.odev_teslimleri (ogrenci_id);
create index if not exists idx_odevler_ders_id on public.odevler (ders_id);
create index if not exists idx_odevler_olusturan_id on public.odevler (olusturan_id);
create index if not exists idx_odevler_program_id on public.odevler (program_id);
create index if not exists idx_sinavlar_ders_id on public.sinavlar (ders_id);
create index if not exists idx_sinavlar_olusturan_id on public.sinavlar (olusturan_id);
